<!doctype html><html><head><meta charset="utf-8"><title>Payslip {{ $entry->employee_number }} — {{ $payroll->period_month }}/{{ $payroll->period_year }}</title><style>body{font-family:Arial,sans-serif;color:#18324b;max-width:800px;margin:35px auto;padding:20px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #1eaa91;padding-bottom:18px}h1{margin:0;font-size:26px}h2{margin:28px 0 8px;font-size:18px}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #dde7ee}.amount{text-align:right;font-weight:600}.total td{font-size:18px;font-weight:bold;border-top:2px solid #18324b}.muted{color:#60798d;font-size:13px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><div class="head"><div><h1>{{ $company->name }}</h1><div class="muted">Salary payslip · {{ \Carbon\Carbon::create($payroll->period_year,$payroll->period_month)->format('F Y') }}</div></div><div><b>{{ $entry->employee_name }}</b><br><span class="muted">{{ $entry->employee_number }}</span></div></div><h2>Earnings</h2><table><tr><td>Basic salary</td><td class="amount">OMR {{ number_format($entry->basic_salary,3) }}</td></tr><tr><td>Housing allowance</td><td class="amount">OMR {{ number_format($entry->housing_allowance,3) }}</td></tr><tr><td>Transport allowance</td><td class="amount">OMR {{ number_format($entry->transport_allowance,3) }}</td></tr><tr><td>Other allowance</td><td class="amount">OMR {{ number_format($entry->other_allowance,3) }}</td></tr><tr><td>Overtime / bonus</td><td class="amount">OMR {{ number_format($entry->overtime_amount+$entry->bonus_amount,3) }}</td></tr><tr class="total"><td>Gross pay</td><td class="amount">OMR {{ number_format($entry->gross_pay,3) }}</td></tr></table><h2>Deductions</h2><table><tr><td>Employee statutory contribution</td><td class="amount">OMR {{ number_format($entry->employee_contribution,3) }}</td></tr><tr><td>Unpaid leave, advance and other deductions</td><td class="amount">OMR {{ number_format($entry->unpaid_leave_deduction+$entry->advance_deduction+$entry->other_deduction,3) }}</td></tr><tr class="total"><td>Net salary payable</td><td class="amount">OMR {{ number_format($entry->net_pay,3) }}</td></tr></table><p class="muted">Prepared in PowerBooks. Payment remains subject to your company approval and Bank Muscat processing. {{ $entry->remarks }}</p></body></html>
